#include "hwio/fds_trace.hpp"
#include <fstream>
#include <algorithm>
#include <stdexcept>
namespace hwio::fds {
Trace::~Trace(){live(false);}
std::vector<TraceEntry> Trace::since(std::uint64_t& cursor,std::uint64_t& lost,unsigned limit)const{std::lock_guard lock(mutex_);const auto floor=written_>ring_.size()?written_-ring_.size():0;if(cursor<floor){lost+=floor-cursor;cursor=floor;}std::vector<TraceEntry> out;const auto count=static_cast<unsigned>(std::min<std::uint64_t>(written_-cursor,std::min(limit,128u)));out.reserve(count);for(unsigned n=0;n<count;++n)out.push_back(ring_[cursor++%ring_.size()]);return out;}
void Trace::live(bool enabled){if(!enabled){live_stop_=true;if(live_worker_.joinable())live_worker_.join();return;}if(live_worker_.joinable())return;live_stop_=false;live_worker_=std::thread([this]{const auto name=L"\\\\.\\pipe\\PSX.HWIO.FdsTrace."+std::to_wstring(GetCurrentProcessId());while(!live_stop_){HANDLE pipe=CreateNamedPipeW(name.c_str(),PIPE_ACCESS_OUTBOUND|FILE_FLAG_OVERLAPPED|FILE_FLAG_FIRST_PIPE_INSTANCE,PIPE_TYPE_BYTE|PIPE_READMODE_BYTE|PIPE_WAIT|PIPE_REJECT_REMOTE_CLIENTS,1,65536,0,0,nullptr);if(pipe==INVALID_HANDLE_VALUE)break;OVERLAPPED ov{};ov.hEvent=CreateEventW(nullptr,TRUE,FALSE,nullptr);auto wait=[&]{while(!live_stop_){const auto result=WaitForSingleObject(ov.hEvent,50);if(result==WAIT_OBJECT_0)return true;if(result==WAIT_FAILED)break;}CancelIoEx(pipe,&ov);DWORD ignored{};GetOverlappedResult(pipe,&ov,&ignored,TRUE);return false;};bool connected=ConnectNamedPipe(pipe,&ov)!=FALSE;if(!connected){const auto error=GetLastError();connected=error==ERROR_PIPE_CONNECTED || (error==ERROR_IO_PENDING && wait());}std::uint64_t cursor{},lost{};const auto start=written();while(connected && !live_stop_){auto entries=since(cursor,lost,32);if(entries.empty()){Sleep(20);continue;}const auto split=std::find_if(entries.begin(),entries.end(),[&](const auto& e){return e.sequence>start;});if(split!=entries.begin() && split!=entries.end()){cursor-=static_cast<std::uint64_t>(entries.end()-split);entries.erase(split,entries.end());}struct Header {char magic[8];std::uint32_t count,flags;std::uint64_t frequency,lost;} header{{'F','D','S','L','I','V','E','1'},static_cast<unsigned>(entries.size()),entries.back().sequence<=start?1u:0u,0,lost};LARGE_INTEGER f{};QueryPerformanceFrequency(&f);header.frequency=static_cast<std::uint64_t>(f.QuadPart);std::array<unsigned char,sizeof(Header)+32*sizeof(TraceEntry)> data{};memcpy(data.data(),&header,sizeof(header));memcpy(data.data()+sizeof(header),entries.data(),entries.size()*sizeof(TraceEntry));ResetEvent(ov.hEvent);DWORD done{};const auto bytes=static_cast<DWORD>(sizeof(header)+entries.size()*sizeof(TraceEntry));const auto ok=WriteFile(pipe,data.data(),bytes,&done,&ov);if(!ok){if(GetLastError()!=ERROR_IO_PENDING || !wait() || !GetOverlappedResult(pipe,&ov,&done,FALSE)){connected=false;break;}}if(done!=bytes){connected=false;break;}}CancelIoEx(pipe,nullptr);DisconnectNamedPipe(pipe);CloseHandle(ov.hEvent);CloseHandle(pipe);}});}
void Trace::record(TraceKind kind,std::uint32_t stream,std::uint64_t generation,std::string_view bytes,std::uint64_t stamp){
    if(!stamp){LARGE_INTEGER time{};QueryPerformanceCounter(&time);stamp=static_cast<std::uint64_t>(time.QuadPart);}
    std::lock_guard lock(mutex_);const auto event=++event_;do{auto& item=ring_[written_%ring_.size()];item={};item.stamp=stamp;item.sequence=++written_;item.generation=generation;item.event=event;item.stream=stream;item.kind=kind;item.size=static_cast<std::uint16_t>(std::min(bytes.size(),item.bytes.size()));memcpy(item.bytes.data(),bytes.data(),item.size);bytes.remove_prefix(item.size);}while(!bytes.empty());
}
std::vector<TraceEntry> Trace::snapshot() const {std::lock_guard lock(mutex_);std::vector<TraceEntry> result;const auto count=std::min<std::uint64_t>(written_,ring_.size());result.reserve(static_cast<std::size_t>(count));auto first=written_-count;if(first && count){const auto cut=ring_[first%ring_.size()].event;while(first<written_ && ring_[first%ring_.size()].event==cut)++first;}for(auto n=first;n<written_;++n)result.push_back(ring_[n%ring_.size()]);return result;}
std::uint64_t Trace::written()const{std::lock_guard lock(mutex_);return written_;}
void Trace::fault_directory(std::filesystem::path path){std::lock_guard lock(mutex_);fault_directory_=std::move(path);}
void Trace::fault(std::string reason){std::filesystem::path path;unsigned index{};{std::lock_guard lock(mutex_);if(!faults_.empty() && faults_.back().first==reason)return;path=fault_directory_;index=fault_index_++%4;}record(TraceKind::fault,0,0,reason);auto entries=snapshot();{std::lock_guard lock(mutex_);if(faults_.size()==4)faults_.pop_front();faults_.emplace_back(reason,entries);}if(!path.empty())try{std::filesystem::create_directories(path);write(path/(L"fault-"+std::to_wstring(index)+L".fdst"),entries);std::ofstream why(path/(L"fault-"+std::to_wstring(index)+L".txt"));why<<reason;}catch(const std::exception& e){record(TraceKind::fault,0,0,std::string("Fault archive error: ")+e.what());}}
std::vector<std::pair<std::string,std::vector<TraceEntry>>> Trace::faults()const{std::lock_guard lock(mutex_);return {faults_.begin(),faults_.end()};}
void Trace::write(const std::filesystem::path& path,std::span<const TraceEntry> entries){if(entries.size()>65536)throw std::runtime_error("FDS trace exceeds 16 MiB");const auto temporary=std::filesystem::path(path.wstring()+L".tmp."+std::to_wstring(GetCurrentThreadId()));try{std::ofstream out(temporary,std::ios::binary|std::ios::trunc);LARGE_INTEGER frequency{};QueryPerformanceFrequency(&frequency);out.write("FDST2\0\0\0",8);const std::uint64_t count=entries.size();out.write(reinterpret_cast<const char*>(&frequency.QuadPart),8);out.write(reinterpret_cast<const char*>(&count),8);out.write(reinterpret_cast<const char*>(entries.data()),static_cast<std::streamsize>(entries.size_bytes()));out.flush();if(!out)throw std::runtime_error("Cannot write FDS trace");out.close();if(!out || !MoveFileExW(temporary.c_str(),path.c_str(),MOVEFILE_REPLACE_EXISTING|MOVEFILE_WRITE_THROUGH))throw std::runtime_error("Cannot commit FDS trace");}catch(...){DeleteFileW(temporary.c_str());throw;}}
std::vector<TraceEntry> Trace::read(const std::filesystem::path& path){std::ifstream in(path,std::ios::binary);char header[8]{};std::uint64_t frequency{},count{};in.read(header,8);in.read(reinterpret_cast<char*>(&frequency),8);in.read(reinterpret_cast<char*>(&count),8);if(!in || memcmp(header,"FDST2\0\0\0",8) || !frequency || count>65536)throw std::runtime_error("Invalid FDS trace header/bounds");std::vector<TraceEntry> result(static_cast<std::size_t>(count));in.read(reinterpret_cast<char*>(result.data()),static_cast<std::streamsize>(result.size()*sizeof(TraceEntry)));if(!in || in.peek()!=EOF)throw std::runtime_error("Truncated/trailing FDS trace");std::uint64_t sequence{};for(const auto& item:result){if(item.size>item.bytes.size() || item.sequence<=sequence || static_cast<unsigned>(item.kind)>static_cast<unsigned>(TraceKind::usb_bitmap))throw std::runtime_error("Invalid FDS trace record");sequence=item.sequence;}return result;}
std::uint64_t Trace::frequency(const std::filesystem::path& path){std::ifstream in(path,std::ios::binary);in.seekg(8);std::uint64_t value{};in.read(reinterpret_cast<char*>(&value),8);if(!in || !value)throw std::runtime_error("Invalid trace clock");return value;}
}
